from review_helpers import *
review('SCENARIO-CTO-001',[
('The charter Annex 9 states that failure to register books of accounts, books of records, official receipts, cash sales, cash invoices, delivery receipts and other collection receipts within fifteen (15) working days from filing a new or renewal business-permit application incurs an administrative fine of PHP5,000.',[(31,'ANNEX','5,000.00')])],['Answer substance supported, but existing PDF20 IDs concern weights and measures, not books registration.','Replace erroneous mapped pages with actual Annex9 PDF31/printed186.'])
review('SCENARIO-CTO-002',[
('The transfer-tax computation cannot be reliably determined from this charter passage: Annex4 literally prints "Transfer Tax is equal to 87% or 1% based on the consideration or the market value whichever is higher." This apparent source anomaly must be clarified; it does not support substituting 0.75% or using 87% as a practical tax rate.',[(11,'Transfer Tax is equal','whichever is higher')]),
('The certification fee table lists PHP50 plus PHP20 for each additional page. Requirements: title photocopy for verification only; notarized Deed of Transfer (1 original); Tax Declaration/Declaration of Real Property Tax Valuation (1 original).',[(11,'Clearances','P 50.00'),(9,'CHECKLIST','CLIENT STEPS')])],['Rendered PDF confirms 87%, so this is not just extraction corruption.','Quarantine computation claim pending authoritative clarification; retain supported certification fee and checklist.','Add PDF9 for actual checklist.'],{'type':'blocking_reference_computation','question':'Obtain authoritative correction/confirmation of the transfer-tax rate; rendered Annex4 says 87% or 1%, while old reference says 0.75% or up to 1%.','source':'CTO PDF11/printed166','blocking':'Do not approve computed tax labels or treat this rate question as fully validated.'},'source_conflict_requires_clarification')
review('SCENARIO-CTO-003',[
('Annex11 states Basic Real Property Tax is 1.5% of assessed value and the additional Special Education Fund levy is 1% of assessed value. Their arithmetic sum is 2.5% of assessed value; this sum is derived from the two stated rates.',[(36,'Section 7. Imposition','shall accrue exclusively to the Special Education Fund (SEF)')])],['Rates supported; identify 2.5% as arithmetic derivation.','Use substantive Annex11 evidence rather than administrative-only pages.'],status='supported')
review('SCENARIO-CTO-004',[
('Annex15, Section72 lists annual fixed delivery-vehicle taxes: motorcycle/motorized tricycle PHP240; delivery jeepney/similar utility vehicle PHP600; truck, van, or any vehicle with six wheels and above PHP1,000; water vessel, barges, ferry boats, tugboats and similar watercraft PHP2,000; airplane/aircraft PHP5,000. The section applies to vehicles used by manufacturers, producers, wholesalers, dealers or retailers in delivery/distribution of the listed products and goods within the City. Preserve the six-wheel row wording when classifying a vehicle.',[(55,'Section 72','Article Ten')])],['Amounts and row associations confirmed.','Retain exact category and scope wording; omit unrelated graduated business-tax table.'],status='supported')
review('SCENARIO-CTO-005',[
('The Professional Tax service lists a TOTAL fee of PHP300. Requirements: unexpired PRC/IBP ID (1 original); PRC/IBP certification for new registrants/passers (1 original); current Davao City address and valid contact number/email address.',[(38,'Section 58','18 Minutes'),(37,'CHECKLIST','CLIENT STEPS')]),
('Register/log in at ptr.davaocity.gov.ph, generate an Order of Payment, then pay at a Miscellaneous Fees counter or the listed Landbank payment portal.',[(37,'1. Visit','City of Davao'),(38,'eservices','Section 58')])],['Restore certification original quantity and new-registrant scope.','The supplied pages give PHP300 and reference Section58 but do not themselves state the annual-period claim; do not add external legal text.'])
review('SCENARIO-CTO-006',[
('Annex14 states an annual basic community tax of PHP5 for liable individuals plus an annual additional tax of PHP1 per PHP1,000 of income, with the additional tax capped at PHP5,000. For husband and wife the additional tax is based on their total property and total gross receipts/earnings. The cap is on additional tax, not the basic-plus-additional total.',[(48,'Individuals liable','Juridical Persons Liable')]),
('For liable corporations, the basic annual tax is PHP500 plus additional tax capped at PHP10,000. The additional schedule is PHP2 per PHP5,000 of Philippine real-property value during the preceding year using the stated real-property-tax valuation, plus PHP2 per PHP5,000 of Philippine business gross receipts/earnings during the preceding year. Intercorporate dividends are included in gross receipts/earnings for this additional tax. The cap is on additional tax.',[(48,'Every corporation','said corporation')])],['Clarify additional-tax caps rather than total-tax caps.','Restore preceding-year basis and source aggregation clauses.'])
